export const BOAT=Object.freeze({width:3,length:5.5,opening:2.60,gangwayWidth:1.9,seatTop:.74,seatRootY:.74-.18419277667999268,footTop:.74-.18419277667999268+.14111661911010742,boardDuration:7.6,waterY:-.35});
export function boatFloor(z){if(z>=4)return .05;if(z>=2.5)return .05+.35*(4-z)/1.5;if(z>=1.5)return .4+(BOAT.footTop-.4)*(2.5-z);return BOAT.footTop;}
export const boatWalkY=z=>Math.max(.05,...feet.map(([vz,y])=>boatFloor(z-vz)-y));
// Outbound feet face +Z. Include the original running pose's maximum sole
// displacement toward the higher side of each ramp; it only lifts feet in Y.
export const boatOutwardWalkY=(z,stride=0)=>Math.max(.05,...feet.map(([vz,y])=>boatFloor(z+vz-.075*Math.abs(stride))-y));
export function boatPoseBottom(pose){const x=Math.max(0,Math.min(1,pose))*100,i=Math.min(99,Math.floor(x));return underside[i]+(underside[i+1]-underside[i])*(x-i);}
